      "text": "Hello."
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "नमस्ते क्या आपको wool and double blanket की जरूरत थी?"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "हूं हूं।"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "माफ़ कीजिए क्या आप अपनी ज़रूरत के बारे में बता सकते हैं?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "आपको किस चीज़ की जानकारी चाहिए?"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "बुलाई थी।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "ठीक है?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आपको woolen double blanket की requirement है सही समझा मैंने?"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "हमारे पास अच्छे sellers available हैं।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "कितनी piece या kilogram चाहिए होगी आपको?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "पाँच kg का blanket मिल सकता है?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "समझ गए आप 5 kg का लेना चाह रहे हैं।"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "चलिए अब bed size के बारे में बता दीजिए single, double या king size चाहिए?"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "आप पाँच किलो"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "double size."
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "बहुत बढ़िया double size।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "बहुत बढ़िया double size note कर लिया।"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "price की जानकारी आप seller से discuss कर सकते हैं।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "अब material में polyester चाहिए या कुछ और?"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "Please tell."
    },
    {
      "i": 24,
      "speaker": "caller",
      "text": "ठीक है material में polyester note कर लिया।"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "price seller से ही discuss कर पाएंगे।"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "अब आपकी city और state बता दीजिए please।"
    },
    {
      "i": 27,
      "speaker": "caller",
      "text": "ठीक है polyester note कर लिया।"
    },
    {
      "i": 28,
      "speaker": "caller",
      "text": "price..."
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "ठीक है polyester note"
    }
  ]
